import { Component, model, input, output, signal, effect, OnInit, OnDestroy, inject } from '@angular/core';
import { HttpErrorResponse, HttpEvent, HttpEventType } from '@angular/common/http';
import { Subscription, interval } from 'rxjs';
import { DocumentoService, DocumentoResponse } from '../../../services/documento.service';
import { environment } from '../../../../environments/environment';
import { extractErrorMessage } from '../../utils/error-utils';

@Component({
  selector: 'app-document-uploader',
  imports: [],
  templateUrl: './document-uploader.html',
  styleUrl: './document-uploader.scss',
})
export class DocumentUploaderComponent implements OnInit, OnDestroy {
  private readonly MIN_ANIMATION_MS = 1200;

  file = model<File | null>(null);
  documentId = model<number | null>(null);
  id = input<string>('');
  label = input<string>('');
  accept = input<string>('.pdf');
  maxSize = input<number>(15);
  required = input<boolean>(false);
  view = output<File>();
  replaceContext = input<{ folio: string; nombreOriginal: string } | null>(null);
  uploadState = signal<'idle' | 'dragging' | 'uploading' | 'failed' | 'success'>('idle');
  progress = signal<number>(0);
  speed = signal<number>(0);
  timeLeft = signal<number>(0);
  errorMessage = signal<string>('');
  previewUrl = signal<string | null>(null);

  tempFile: File | null = null;
  private documentoService = inject(DocumentoService);
  private uploadSubscription: Subscription | null = null;
  private progressAnimSubscription: Subscription | null = null;
  private realProgress = 0;
  private lastLoaded = 0;
  private lastTimestamp = 0;
  private animationStartTime = 0;
  private uploadCompleted = false;
  private pendingDocumentId: number | null = null;

  constructor() {
    effect(() => {
      const currentFile = this.file();
      if (currentFile && this.uploadState() === 'idle') {
        this.uploadState.set('success');
        this.generatePreview(currentFile);
      } else if (!currentFile && this.uploadState() === 'success') {
        this.resetState();
      }
    });

    effect(() => {
      this.documentId();
      this.restoreFromDocumentId();
    });
  }

  ngOnInit(): void {
    const initialFile = this.file();
    if (initialFile) {
      this.uploadState.set('success');
      this.generatePreview(initialFile);
    } else if (this.id()) {
      if (typeof localStorage !== 'undefined') {
        const cached = localStorage.getItem('doc_upload_' + this.id());
        if (cached) {
          const meta: { id?: number; name?: string; size?: number; type?: string } = JSON.parse(cached);
          if (meta.id) {
            this.documentId.set(meta.id);
          }
        }
      }
      this.restoreFromDocumentId();
    }
  }

  ngOnDestroy(): void {
    this.cancelUpload();
  }

  onDragOver(event: DragEvent): void {
    event.preventDefault();
    event.stopPropagation();
    if (this.uploadState() === 'idle') {
      this.uploadState.set('dragging');
    }
  }

  onDragLeave(event: DragEvent): void {
    event.preventDefault();
    event.stopPropagation();
    if (this.uploadState() === 'dragging') {
      this.uploadState.set('idle');
    }
  }

  onDrop(event: DragEvent): void {
    event.preventDefault();
    event.stopPropagation();
    this.uploadState.set('idle');

    const files = event.dataTransfer?.files;
    if (files && files.length > 0) {
      this.handleFile(files[0]);
    }
  }

  onFileSelected(event: Event): void {
    const input = event.target as HTMLInputElement;
    if (input?.files?.length) {
      this.handleFile(input.files[0]);
      input.value = '';
    }
  }

  handleFile(file: File): void {
    const extension = '.' + file.name.split('.').pop()?.toLowerCase();
    const acceptedTypes = this.accept()
      .split(',')
      .map((t) => t.trim().toLowerCase());

    const isAccepted = acceptedTypes.some((type) => {
      if (type.startsWith('.')) {
        return extension === type;
      } else if (type.includes('/*')) {
        const category = type.split('/')[0];
        return file.type.startsWith(category + '/');
      }
      return file.type === type;
    });

    if (!isAccepted) {
      this.errorMessage.set(`Formato inválido. Solo se aceptan: ${this.accept()}`);
      return;
    }

    const maxSizeInBytes = this.maxSize() * 1024 * 1024;
    if (file.size > maxSizeInBytes) {
      this.errorMessage.set(`El archivo supera el límite permitido de ${this.maxSize()} MB`);
      return;
    }

    this.errorMessage.set('');
    this.tempFile = file;
    this.uploadState.set('uploading');
    this.progress.set(0);
    this.speed.set(0);
    this.timeLeft.set(0);
    this.realProgress = 0;
    this.lastLoaded = 0;
    this.lastTimestamp = 0;
    this.uploadCompleted = false;
    this.documentId.set(null);
    if (this.id()) {
      localStorage.removeItem('doc_upload_' + this.id());
    }

    this.cancelUpload();
    this.startProgressAnimation();

    const ctx = this.replaceContext();
    const request$ = ctx
      ? this.documentoService.reemplazarDocumento(ctx.folio, ctx.nombreOriginal, file)
      : this.documentoService.subirDocumento(file);
    this.uploadSubscription = request$.subscribe({
      next: (event: HttpEvent<DocumentoResponse>) => {
        if (event.type === HttpEventType.UploadProgress && event.total) {
          this.realProgress = Math.round((event.loaded / event.total) * 100);

          const now = Date.now();
          if (this.lastLoaded > 0 && this.lastTimestamp > 0) {
            const deltaBytes = event.loaded - this.lastLoaded;
            const deltaSec = (now - this.lastTimestamp) / 1000;
            if (deltaSec > 0 && deltaBytes > 0) {
              const instantSpeedMB = (deltaBytes / deltaSec) / (1024 * 1024);
              const currentSpeed = this.speed();
              if (currentSpeed > 0) {
                this.speed.set(+(currentSpeed * 0.7 + instantSpeedMB * 0.3).toFixed(1));
              } else {
                this.speed.set(+instantSpeedMB.toFixed(1));
              }
            }
          }
          this.lastLoaded = event.loaded;
          this.lastTimestamp = now;

          const remainingBytes = event.total - event.loaded;
          const speedMB = this.speed();
          if (speedMB > 0.01) {
            this.timeLeft.set(Math.ceil(remainingBytes / (speedMB * 1024 * 1024)));
          }
        } else if (event.type === HttpEventType.Response) {
          this.uploadCompleted = true;
          this.realProgress = 100;
          const responseBody = event.body;
          if (responseBody?.data?.id) {
            this.pendingDocumentId = responseBody.data.id;
          } else {
            this.stopProgressAnimation();
            this.uploadState.set('failed');
            this.errorMessage.set('La respuesta del servidor no contiene el ID del documento');
          }
        }
      },
      error: (error: HttpErrorResponse) => {
        this.stopProgressAnimation();
        this.uploadState.set('failed');
        this.errorMessage.set(extractErrorMessage(error));
      },
    });
  }

  retryUpload(): void {
    if (!this.tempFile) return;
    this.handleFile(this.tempFile);
  }

  removeSelectedFile(): void {
    const docId = this.documentId();
    if (docId) {
      this.documentoService.deleteDocumento(docId).subscribe({
        next: () => this.clearLocalState(),
        error: () => this.clearLocalState(),
      });
    } else {
      this.clearLocalState();
    }
  }

  private clearLocalState(): void {
    this.file.set(null);
    this.documentId.set(null);
    this.resetState();
    if (this.id()) {
      localStorage.removeItem('doc_upload_' + this.id());
    }
  }

  viewSelectedFile(): void {
    const currentFile = this.file();
    if (currentFile) {
      this.view.emit(currentFile);
    }
  }

  onKeyDown(event: KeyboardEvent, fileInput: HTMLInputElement): void {
    if (event.key === 'Enter' || event.key === ' ') {
      event.preventDefault();
      fileInput.click();
    }
  }

  formatBytes(bytes: number, decimals = 1): string {
    if (bytes === 0) return '0 Bytes';
    const k = 1024;
    const dm = decimals < 0 ? 0 : decimals;
    const sizes = ['Bytes', 'KB', 'MB', 'GB'];
    const i = Math.floor(Math.log(bytes) / Math.log(k));
    return parseFloat((bytes / Math.pow(k, i)).toFixed(dm)) + ' ' + sizes[i];
  }

  getFileExtension(filename: string): string {
    return filename.split('.').pop()?.toUpperCase() || '';
  }

  isImage(filename: string): boolean {
    const ext = filename.split('.').pop()?.toLowerCase();
    return ['png', 'jpg', 'jpeg', 'gif', 'webp'].includes(ext || '');
  }

  private restoreFromDocumentId(): void {
    const docId = this.documentId();
    if (docId === null || this.uploadState() !== 'idle') return;

    const uploaderId = this.id();
    let name = 'documento.pdf';
    let size = 0;
    let type = 'application/pdf';

    if (uploaderId) {
      const cached = localStorage.getItem('doc_upload_' + uploaderId);
      if (cached) {
        const meta: { id?: number; name?: string; size?: number; type?: string } = JSON.parse(cached);
        if (meta.id) {
          this.documentId.set(meta.id);
          name = meta.name ?? name;
          size = meta.size ?? size;
          type = meta.type ?? type;
        }
      }
    }

    const fakeFile = new File([], name, { type });
    Object.defineProperty(fakeFile, 'size', { value: size, writable: false });
    this.file.set(fakeFile);
    this.uploadState.set('success');
    this.generatePreview(fakeFile);
  }

  private startProgressAnimation(): void {
    this.animationStartTime = Date.now();
    this.uploadCompleted = false;
    this.stopProgressAnimation();

    this.progressAnimSubscription = interval(50).subscribe(() => {
      const elapsed = Date.now() - this.animationStartTime;
      const timeCap = Math.min(100, Math.round((elapsed / this.MIN_ANIMATION_MS) * 100));

      const target = this.uploadCompleted
        ? timeCap
        : Math.min(this.realProgress, timeCap);

      const current = this.progress();
      if (current < target) {
        const step = Math.max(2, Math.ceil((target - current) / 3));
        this.progress.set(Math.min(target, current + step));
      }

      if (this.uploadCompleted && this.progress() >= 100) {
        this.stopProgressAnimation();
        this.progress.set(100);
        if (this.tempFile) {
          this.completeUpload(this.tempFile);
        }
      }
    });
  }

  private stopProgressAnimation(): void {
    this.progressAnimSubscription?.unsubscribe();
    this.progressAnimSubscription = null;
  }

  private completeUpload(file: File): void {
    this.uploadState.set('success');
    this.file.set(file);
    
    let docIdToSave = this.documentId();

    if (this.pendingDocumentId !== null) {
      const docId = this.pendingDocumentId;
      docIdToSave = docId;
      this.pendingDocumentId = null;
      setTimeout(() => {
        this.documentId.set(docId);
      }, 800);
    }
    
    this.generatePreview(file);
    if (this.id() && docIdToSave) {
      localStorage.setItem('doc_upload_' + this.id(), JSON.stringify({
        id: docIdToSave,
        name: file.name,
        size: file.size,
        type: file.type
      }));
    }
  }

  private generatePreview(file: File): void {
    if (file.type.startsWith('image/')) {
      if (this.tempFile === null && this.documentId() && file.slice().size === 0) {
        this.previewUrl.set(`${environment.apiUrl}/documentos/${this.documentId()}`);
      } else {
        const reader = new FileReader();
        reader.onload = (e: ProgressEvent<FileReader>) => {
          const result = e.target?.result;
          if (typeof result === 'string') {
            this.previewUrl.set(result);
          }
        };
        reader.readAsDataURL(file);
      }
    } else {
      this.previewUrl.set(null);
    }
  }

  private resetState(): void {
    this.cancelUpload();
    this.tempFile = null;
    this.uploadState.set('idle');
    this.progress.set(0);
    this.previewUrl.set(null);
    this.uploadCompleted = false;
    this.realProgress = 0;
  }

  private cancelUpload(): void {
    this.stopProgressAnimation();
    if (this.uploadSubscription) {
      this.uploadSubscription.unsubscribe();
      this.uploadSubscription = null;
    }
  }
}
